// Background music.
//
// Two tracks — a cruising theme and a battle theme — crossfaded by the
// game state. If `public/music/manifest.json` exists (generated by
// scripts/generate-music.mjs against the ElevenLabs Music API) the real
// tracks play; otherwise a procedural synth score keeps the night
// scored, so the game is never silent and ships with no audio assets.

export type MusicMood = "cruise" | "battle";

const MANIFEST = "/music/manifest.json";
const FADE = 1.6; // seconds

export class Music {
  enabled = true;
  private ctx: AudioContext;
  private master: GainNode;
  private volume = 0.32;

  // Generated-track path
  private tracks = new Map<MusicMood, HTMLAudioElement>();
  private gains = new Map<MusicMood, GainNode>();
  private haveTracks = false;

  // Procedural fallback
  private synth: SynthScore | null = null;

  private mood: MusicMood = "cruise";
  private started = false;

  constructor(ctx: AudioContext) {
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.volume;
    this.master.connect(ctx.destination);

    fetch(MANIFEST)
      .then((r) => (r.ok ? r.json() : null))
      .then((list: string[] | null) => {
        if (!Array.isArray(list) || list.length === 0) return;
        for (const mood of ["cruise", "battle"] as MusicMood[]) {
          if (!list.includes(mood)) continue;
          const el = new Audio(`/music/${mood}.mp3`);
          el.loop = true;
          el.crossOrigin = "anonymous";
          const src = ctx.createMediaElementSource(el);
          const g = ctx.createGain();
          g.gain.value = 0;
          src.connect(g).connect(this.master);
          this.tracks.set(mood, el);
          this.gains.set(mood, g);
        }
        this.haveTracks = this.tracks.size > 0;
        if (this.haveTracks && this.started) {
          this.synth?.stop();
          this.synth = null;
          this.playTracks();
        }
      })
      .catch(() => {});
  }

  /** Call from a user gesture — audio contexts need one. */
  start(): void {
    if (this.started) return;
    this.started = true;
    if (this.haveTracks) this.playTracks();
    else {
      this.synth = new SynthScore(this.ctx, this.master);
      this.synth.setMood(this.mood);
    }
  }

  private playTracks(): void {
    for (const [mood, el] of this.tracks) {
      void el.play().catch(() => {});
      this.fadeTo(mood, mood === this.mood ? 1 : 0);
    }
  }

  private fadeTo(mood: MusicMood, target: number): void {
    const g = this.gains.get(mood);
    if (!g) return;
    g.gain.cancelScheduledValues(this.ctx.currentTime);
    g.gain.setTargetAtTime(target, this.ctx.currentTime, FADE / 3);
  }

  /** Cruise while driving, battle during a rival fight or a duel. */
  setMood(mood: MusicMood): void {
    if (mood === this.mood) return;
    this.mood = mood;
    if (this.haveTracks) {
      this.fadeTo("cruise", mood === "cruise" ? 1 : 0);
      this.fadeTo("battle", mood === "battle" ? 1 : 0);
    } else {
      this.synth?.setMood(mood);
    }
  }

  toggle(): boolean {
    this.enabled = !this.enabled;
    this.master.gain.setTargetAtTime(
      this.enabled ? this.volume : 0,
      this.ctx.currentTime,
      0.15
    );
    return this.enabled;
  }

  setVolume(v: number): void {
    this.volume = Math.max(0, Math.min(1, v));
    if (this.enabled) this.master.gain.setTargetAtTime(this.volume, this.ctx.currentTime, 0.1);
  }

  dispose(): void {
    this.synth?.stop();
    for (const el of this.tracks.values()) el.pause();
  }
}

// ---------------------------------------------------------------------
// Procedural fallback: a slow minor-key arpeggio over a sub bass, with a
// bit of an eighth-note pulse. Deliberately sparse — it sits under the
// engine rather than competing with it.

const CRUISE = [
  [220, 261.63, 329.63, 392.0], // Am
  [174.61, 220, 261.63, 349.23], // F
  [196, 246.94, 293.66, 392.0], // G
  [220, 261.63, 329.63, 440.0], // Am
];
const BATTLE = [
  [146.83, 174.61, 220, 293.66], // Dm — darker, faster
  [155.56, 185, 233.08, 311.13], // Eb
  [130.81, 155.56, 196, 261.63], // Cm
  [146.83, 174.61, 233.08, 293.66],
];

class SynthScore {
  private ctx: AudioContext;
  private out: GainNode;
  private timer: ReturnType<typeof setInterval> | null = null;
  private step = 0;
  private mood: MusicMood = "cruise";
  private pad: OscillatorNode[] = [];
  private padGain: GainNode;

  constructor(ctx: AudioContext, out: GainNode) {
    this.ctx = ctx;
    this.out = out;

    // Sustained pad underneath everything
    this.padGain = ctx.createGain();
    this.padGain.gain.value = 0.05;
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = 700;
    this.padGain.connect(filter).connect(out);
    for (const detune of [-6, 6]) {
      const o = ctx.createOscillator();
      o.type = "sawtooth";
      o.frequency.value = 110;
      o.detune.value = detune;
      o.connect(this.padGain);
      o.start();
      this.pad.push(o);
    }

    this.schedule();
  }

  setMood(mood: MusicMood): void {
    this.mood = mood;
    this.schedule();
    // Battle drops the pad a fifth and opens it up
    const root = mood === "battle" ? 73.42 : 110;
    for (const o of this.pad) o.frequency.setTargetAtTime(root, this.ctx.currentTime, 0.4);
    this.padGain.gain.setTargetAtTime(mood === "battle" ? 0.08 : 0.05, this.ctx.currentTime, 0.6);
  }

  private schedule(): void {
    if (this.timer) clearInterval(this.timer);
    const beat = this.mood === "battle" ? 300 : 460;
    this.timer = setInterval(() => this.tick(), beat);
  }

  private tick(): void {
    const chords = this.mood === "battle" ? BATTLE : CRUISE;
    const chord = chords[Math.floor(this.step / 4) % chords.length];
    const note = chord[this.step % chord.length];
    this.step++;

    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    o.type = this.mood === "battle" ? "square" : "triangle";
    o.frequency.value = note * 2;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(this.mood === "battle" ? 0.07 : 0.05, t + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.55);
    o.connect(g).connect(this.out);
    o.start(t);
    o.stop(t + 0.6);
  }

  stop(): void {
    if (this.timer) clearInterval(this.timer);
    for (const o of this.pad) o.stop();
  }
}
